insert into public.questions
(id,topic,question,option_a,option_b,option_c,option_d,correct_answer,explanation)
values
(1,'SAP Architecture','Which layer in a typical SAP three-tier architecture is responsible for executing ABAP programs?','Presentation layer','Application layer','Database layer','Network layer','B','The application layer contains the ABAP runtime and executes application logic.'),
(2,'SAP Architecture','Which database technology is the foundation of SAP HANA?','Disk-only relational storage','In-memory columnar database technology','Hierarchical file database','Tape-based database','B','SAP HANA is an in-memory database with column-oriented storage as a core technology.'),
(3,'SAP Architecture','Which component normally provides the user interface for an SAP GUI transaction?','Database server','Presentation layer','Message server','Enqueue server','B','SAP GUI belongs to the presentation tier.'),
(4,'SAP Architecture','What is the primary purpose of the SAP message server?','Store application tables','Manage logical locks','Provide communication and load balancing between application servers','Compile ABAP programs','C','The message server manages communication between application servers and supports logon/load distribution.'),
(5,'ABAP Dictionary','Which ABAP Dictionary object defines the technical attributes of a database table field?','Domain','Data element','Search help','Lock object','B','A data element defines semantic information and refers to a domain for technical attributes.'),
(6,'ABAP Dictionary','What does a domain primarily define?','Business meaning only','Technical properties such as data type and length','Database authorization','Program flow','B','Domains define technical characteristics such as data type, length, decimals, and possible fixed values.'),
(7,'ABAP Dictionary','Which Dictionary object is used to define relationships between database tables for input checks and documentation?','Foreign key','Package','Message class','Transaction code','A','A foreign key defines a relationship between fields, commonly for check-table validation.'),
(8,'ABAP Dictionary','Which object can provide F4 input help for a field?','Search help','Lock object','View cluster','Package','A','Search helps provide input help.'),
(9,'ABAP Dictionary','What is a transparent table in ABAP Dictionary?','A table stored only in memory','A Dictionary table with a corresponding physical database table','A temporary internal table','A table containing only text','B','A transparent table has a corresponding table in the underlying database.'),
(10,'ABAP Dictionary','Which Dictionary object is used to define database locking logic?','Lock object','Search help','Data element','Structure','A','Lock objects generate enqueue/dequeue function modules for logical locking.'),
(11,'Data Objects','Which declaration is an inline declaration?','DATA lv_name TYPE string.','DATA(lv_name) = ''SAP''.','TYPES lv_name TYPE string.','FIELD-SYMBOLS <name> TYPE string.','B','DATA(...) in a suitable operand position creates an inline-declared variable.'),
(12,'Data Objects','What is a key advantage of inline declarations?','They eliminate all type checking','They let ABAP derive a suitable type from context','They create database tables','They bypass syntax checks','B','Inline declarations reduce boilerplate while retaining ABAP''s type system.'),
(13,'Data Objects','Which statement creates a field symbol inline in a LOOP?','LOOP AT itab INTO DATA(ls_row).','LOOP AT itab ASSIGNING FIELD-SYMBOL(<ls_row>).','LOOP itab FIELD <ls_row>.','LOOP AT itab USING <ls_row>.','B','FIELD-SYMBOLS(...) can be declared inline in suitable ASSIGNING positions.'),
(14,'Data Objects','Which predefined ABAP type is suitable for character strings with variable length?','c','n','string','d','C','STRING is a dynamically sized character string type.'),
(15,'Data Objects','What does the VALUE constructor operator do?','Deletes an object','Constructs a value of a specified or inferred type','Commits a database transaction','Starts a debugger','B','VALUE constructs data objects, structures, and internal tables.'),
(16,'Open SQL','Which statement is used to read rows from a database table in modern ABAP SQL?','SELECT','READ DATABASE','FETCH TABLE','GET TABLE','A','SELECT is the Open SQL statement for database reads.'),
(17,'Open SQL','Why is Open SQL preferred over database-specific SQL in ABAP applications?','It only works on HANA','It is database-independent and integrated with the ABAP runtime','It bypasses authorization checks','It prevents all performance issues','B','Open SQL provides a database-independent abstraction and ABAP integration.'),
(18,'Open SQL','Which clause limits rows returned by a SELECT?','UP TO','LIMITED BY','ROWS ONLY','MAXIMUM','A','UP TO n ROWS limits the result set.'),
(19,'Open SQL','What does SELECT SINGLE generally request?','Every matching row','One matching database row','One internal-table row','A database lock','B','SELECT SINGLE is intended to retrieve a single row matching the specified key/condition.'),
(20,'Open SQL','Which addition can sort rows returned by a SELECT?','SORT BY','ORDER BY','SEQUENCE BY','RANK BY','B','ORDER BY specifies the sort order of a result set.'),
(21,'Open SQL','Which Open SQL feature can combine data from multiple database sources using a relationship condition?','JOIN','APPEND','COLLECT','CONCATENATE','A','JOIN combines rows from multiple data sources.'),
(22,'Open SQL','What is a common performance problem with SELECT inside a LOOP over database data?','It always causes syntax errors','It can cause many database round trips','It automatically creates indexes','It converts all data to XML','B','Repeated database access can create the classic SELECT-in-LOOP performance problem.'),
(23,'Open SQL','Which approach is generally preferable when all required data can be retrieved in one database operation?','Repeated SELECT in a loop','A set-based SELECT','CALL TRANSACTION repeatedly','WRITE statements','B','Set-based database access usually reduces round trips and lets the database optimize the operation.'),
(24,'Open SQL','Which expression is used to remove duplicate rows from a result set?','DISTINCT','UNIQUE ROWS','DEDUP','ONLY ONCE','A','DISTINCT removes duplicate result rows.'),
(25,'Open SQL','Which statement changes existing database rows?','UPDATE','CHANGE TABLE','MODIFY SQL ONLY','ALTER ROW','A','UPDATE changes existing rows according to its WHERE condition.'),
(26,'Modularization','Which modularization unit can be called with PERFORM?','Subroutine (FORM)','Function module only','Class method only','CDS view','A','FORM routines are called with PERFORM.'),
(27,'Modularization','Which modularization unit is managed in a function group?','Function module','FORM only','CDS entity','Database index','A','Function modules belong to function groups.'),
(28,'Modularization','What is a main advantage of modularization?','It makes all code global','It improves reuse, readability, and maintainability','It disables testing','It removes the need for types','B','Breaking logic into units improves structure and reuse.'),
(29,'Modularization','Which ABAP construct is intended for reusable object-oriented behavior?','Method','Selection option','Domain','Search help','A','Methods encapsulate reusable behavior in classes.'),
(30,'Modularization','What is an INCLUDE program mainly used for?','To include reusable source code in another program','To create database locks','To define a HANA schema','To replace all function modules','A','Includes allow source-code modularization and reuse within programs.'),
(31,'Selection Screens','Which statement defines a parameter on a selection screen?','PARAMETERS p_bukrs TYPE bukrs.','INPUT p_bukrs.','SCREEN PARAM p_bukrs.','SELECT PARAM p_bukrs.','A','PARAMETERS defines an elementary input field on the selection screen.'),
(32,'Selection Screens','Which statement defines a range/select-option?','SELECT-OPTIONS s_bukrs FOR bkpf-bukrs.','RANGES-ONLY s_bukrs.','RANGE PARAM s_bukrs.','SELECT RANGE s_bukrs.','A','SELECT-OPTIONS creates a selection table with low/high and sign/option.'),
(33,'Selection Screens','Which event is used to process selection-screen input before START-OF-SELECTION?','AT SELECTION-SCREEN','TOP-OF-PAGE','END-OF-SELECTION','INITIALIZATION ONLY','A','AT SELECTION-SCREEN is used for validation and processing of selection-screen input.'),
(34,'Selection Screens','Which event is commonly used to provide default values before the selection screen is displayed?','INITIALIZATION','START-OF-SELECTION','END-OF-SELECTION','TOP-OF-PAGE','A','INITIALIZATION runs before the selection screen and is commonly used for defaults.'),
(35,'Selection Screens','Which addition makes a parameter a checkbox?','AS CHECKBOX','CHECKED ONLY','WITH CHECK','BOXED','A','PARAMETERS ... AS CHECKBOX creates a checkbox.'),
(36,'Reporting','Which event is normally the main processing event after selection-screen processing?','START-OF-SELECTION','LOAD-OF-PROGRAM','TOP-OF-PAGE','AT LINE-SELECTION','A','START-OF-SELECTION is the standard main processing event.'),
(37,'Reporting','Which statement writes output to a classical list?','WRITE','DISPLAY','PRINTLINE','LIST-OUT','A','WRITE produces classical list output.'),
(38,'Reporting','Which event can be triggered when a user double-clicks a classical list line?','AT LINE-SELECTION','AT USER-COMMAND ONLY','AT NEW-PAGE','ON DOUBLECLICK','A','AT LINE-SELECTION handles line-selection actions such as double-clicks in classical lists.'),
(39,'Reporting','Which statement is used to define a user command in a classical list?','SET USER-COMMAND','ADD COMMAND','DEFINE FUNCTION','CREATE USER COMMAND','A','SET USER-COMMAND assigns a function code to the current list interaction.'),
(40,'Reporting','What is an interactive report primarily intended to provide?','User-driven navigation from list output to more detail','Database administration','ABAP compilation','Transport management','A','Interactive reporting lets users navigate and react to list selections.'),
(41,'Function Modules','Which transaction is used to create and maintain function modules?','SE37','SE11','SE80','ST22','A','SE37 is the Function Builder transaction.'),
(42,'Function Modules','What is a function group?','A container for related function modules and their global data','A database schema','A transport request','A selection screen','A','Function groups contain related function modules and supporting global declarations.'),
(43,'Function Modules','Which parameter type is used to pass data into a function module?','IMPORTING','DISPLAYING','SELECTING','READONLY','A','IMPORTING parameters receive values from the caller.'),
(44,'Function Modules','Which parameter type is used to return values from a function module to its caller?','EXPORTING','SCREENING','SELECT-OPTIONS','EVENTING','A','EXPORTING parameters pass values from the function module to the caller.'),
(45,'Function Modules','What is the purpose of an EXCEPTIONS section in a classic function module interface?','Define named classic exceptions that can be raised','Define database indexes','Create classes','Create selection options','A','Classic function modules can define named exceptions in their interface.'),
(46,'Enhancements','What is a BAdI?','A Business Add-In enhancement technique based on object-oriented concepts','A database table','A report event','A transport type','A','BAdIs provide enhancement points using object-oriented interfaces/classes.'),
(47,'Enhancements','What is a customer exit?','A predefined enhancement location intended for customer-specific logic','A database backup','A HANA calculation view','A transport request','A','A customer exit is a predefined enhancement location intended for customer-specific customer logic.'),
(48,'Enhancements','Which transaction is commonly associated with the Enhancement Framework and enhancement implementations?','SE20','SE38','SM37','STMS','A','SE20 is used for enhancement framework-related administration.'),
(49,'Enhancements','What is the key benefit of enhancement techniques over modifying SAP standard code?','They preserve standard code and improve upgrade compatibility','They disable transports','They remove authorization checks','They require no testing','A','Enhancements allow customer logic without directly modifying standard SAP source.'),
(50,'Enhancements','A BAdI is generally based on which concept?','Interface and implementing class','Database trigger only','Selection option','FORM routine only','A','BAdIs use an interface and implementation classes.'),
(51,'OOP ABAP','Which keyword starts a class definition in ABAP Objects?','CLASS','OBJECT','DEFINE CLASS','BEGIN CLASS','A','ABAP class definitions start with CLASS ... DEFINITION.'),
(52,'OOP ABAP','Which visibility section allows access only within the class and its friends?','PRIVATE','PUBLIC','GLOBAL','EXTERNAL','A','PRIVATE members are restricted to the class context (subject to ABAP visibility rules such as friends).'),
(53,'OOP ABAP','What is inheritance?','A subclass reuses and specializes behavior/data from a superclass','Copying a database table','Creating a function module','Converting Open SQL to Native SQL','A','Inheritance allows a subclass to derive from a superclass.'),
(54,'OOP ABAP','What is polymorphism?','The same interface/reference can work with different concrete implementations','A way to lock tables','A way to create domains','A method of sorting internal tables','A','Polymorphism allows code to operate through a common type while behavior depends on the actual object.'),
(55,'OOP ABAP','Which ABAP keyword is used to instantiate an object?','CREATE OBJECT','NEW OBJECT ONLY','MAKE OBJECT','INSTANCE','A','CREATE OBJECT is the classic instantiation statement; NEW is the modern constructor operator.'),
(56,'ABAP Test','Which framework is used for unit tests in ABAP Objects?','ABAP Unit','SAPscript','Smart Forms','STMS','A','ABAP Unit provides integrated unit testing for ABAP.'),
(57,'ABAP Test','Which class is commonly used as the superclass for ABAP Unit test classes?','CL_ABAP_UNIT_ASSERT','CL_TEST_BASE','CL_UNIT','CL_ABAP_TEST','A','ABAP Unit uses CL_ABAP_UNIT_ASSERT for assertions; test classes are declared with FOR TESTING.'),
(58,'ABAP Test','Which addition marks a method as a test method in ABAP Unit?','FOR TESTING','TEST METHOD','UNIT TEST','ASSERT METHOD','A','Test methods are declared with FOR TESTING.'),
(59,'ABAP Test','What should a unit test primarily verify?','A small unit of application behavior in isolation','The entire production landscape','Network bandwidth','Transport routes','A','Unit tests focus on small, testable units of behavior.'),
(60,'ABAP Test','Why are test doubles useful?','They isolate the unit under test from dependencies','They increase database size','They replace syntax checking','They create SAP users','A','Test doubles simulate dependencies to make tests deterministic and isolated.'),
(61,'Adobe Forms','Which transaction is used to maintain Adobe Forms in SAP?','SFP','SE37','SMARTFORMS','SO10','A','SFP is the Form Builder transaction for Adobe Forms.'),
(62,'Adobe Forms','Adobe Forms typically use which technology for form layout?','Adobe PDF-based form technology','Classical list only','SAPscript only','HTML mail only','A','SAP Adobe Forms use Adobe form technology and PDF rendering.'),
(63,'Smart Forms','Which transaction is used to maintain Smart Forms?','SMARTFORMS','SFP','SE71','SE37','A','SMARTFORMS is the transaction for Smart Forms.'),
(64,'SAPscript','Which transaction is associated with SAPscript form maintenance?','SE71','SFP','SMARTFORMS','SE11','A','SE71 is used for SAPscript forms.'),
(65,'Forms','What is a key reason to use forms technologies in SAP?','Generate formatted business documents for printing or output','Create database indexes','Manage Linux processes','Compile HANA SQLScript','A','Forms are used to produce formatted documents such as invoices and purchase orders.'),
(66,'In-App Extensibility','What is the main goal of in-app extensibility?','Adapt SAP applications within supported extension capabilities without modifying standard code','Replace the database','Disable upgrades','Write kernel code','A','In-app extensibility supports supported adaptations within the application.'),
(67,'In-App Extensibility','Which principle is central to clean-core development?','Keep the SAP standard as untouched as possible and use released extension mechanisms','Modify SAP standard directly','Avoid APIs','Put all custom logic in the kernel','A','Clean core emphasizes released APIs and extension points instead of modifications.'),
(68,'Debugging','Which transaction is commonly used to execute and debug an ABAP program?','SE38','SE11','SE37','SM50','A','SE38 can execute and debug ABAP reports.'),
(69,'Debugging','What is a breakpoint?','A point where program execution can pause for debugging','A database index','A transport lock','A form window','A','Breakpoints pause execution so runtime state can be inspected.'),
(70,'Debugging','What is a watchpoint used for?','Pause execution when a specified data value changes or meets a condition','Create a database table','Start a background job','Generate a form','A','Watchpoints stop execution when the monitored condition becomes true.'),
(71,'Debugging','Which transaction can be used to analyze ABAP runtime errors/dumps?','ST22','SM37','SE16','SFP','A','ST22 displays ABAP short dumps.'),
(72,'RAP','What does RAP stand for in SAP ABAP?','RESTful Application Programming Model','Remote ABAP Processing','Rapid Application Program','REST ABAP Protocol','A','RAP is SAP''s RESTful Application Programming Model.'),
(73,'RAP','Which artifact commonly defines the semantic data model in RAP?','CDS view entity','Smart Form','Function group','Selection screen','A','CDS view entities are central to RAP data modeling.'),
(74,'RAP','What is a behavior definition in RAP used for?','Define transactional behavior such as create, update, delete, actions, and validations','Define printer layouts','Define Linux permissions','Define database backups','A','Behavior definitions describe transactional behavior of RAP business objects.'),
(75,'RAP','What is a service definition in RAP?','It defines which data/behavior entities are exposed as a service','It defines a database index','It defines a function group','It defines a GUI status','A','Service definitions select the entities to be exposed.'),
(76,'RAP','What is a service binding used for?','Bind a service definition to a communication protocol/runtime such as OData','Create a database table','Define a selection screen','Run ABAP Unit','A','Service bindings expose RAP services using a chosen protocol such as OData V4.'),
(77,'RAP','Which protocol is commonly used to expose RAP services?','OData','FTP','SMTP','SNMP','A','RAP commonly exposes services using OData, especially OData V4.'),
(78,'RAP','What is a determination in RAP?','Logic that derives or adjusts data based on defined transactional events','A database index','A print form','A user role','A','Determinations derive or modify data in response to behavior processing.'),
(79,'RAP','What is a validation in RAP?','Logic that checks whether data is valid before a transactional operation proceeds','A UI theme','A database backup','A transport layer','A','Validations check business consistency and can prevent invalid transactions.'),
(80,'RAP','What is a RAP action?','A business operation explicitly triggered by a consumer','A database trigger','A selection option','A function group','A','Actions represent explicit business operations beyond standard CRUD.'),
(81,'SAP Joule','In the SAP development context, what is Joule?','SAP''s generative AI copilot/assistant experience','A database engine','A transport protocol','A form designer','A','Joule is SAP''s generative AI assistant integrated into SAP experiences.'),
(82,'BTP','What does SAP BTP stand for?','SAP Business Technology Platform','SAP Business Transaction Protocol','SAP Base Transport Package','SAP Business Testing Program','A','BTP stands for SAP Business Technology Platform.'),
(83,'BTP','Which capability is commonly associated with SAP BTP?','Application development, integration, data and analytics, and AI services','Only payroll processing','Only ABAP syntax checking','Only printer management','A','BTP provides services across application development, integration, data/analytics, and AI.'),
(84,'BTP','What is SAP Build Launchpad primarily used for?','Providing a central entry point to business applications','Running database backups','Compiling ABAP','Creating SAPscript forms','A','Launchpad provides a unified access point for applications and content.'),
(85,'Side-by-Side','What does side-by-side extensibility generally mean?','Building extensions outside the core SAP application, often on SAP BTP','Modifying SAP kernel source','Changing SAP standard tables directly','Creating a local printer queue','A','Side-by-side extensions are decoupled from the core and often run on BTP.'),
(86,'Side-by-Side','Why is side-by-side extensibility useful for clean core?','It reduces custom code inside the SAP core','It requires more modifications','It disables APIs','It prevents integration','A','External extensions keep custom functionality decoupled from the core.'),
(87,'Performance','Which transaction is used for SQL Trace in ABAP systems?','ST05','ST22','SM37','SE71','A','ST05 provides SQL trace and other trace functions.'),
(88,'Performance','Which tool is used to analyze ABAP runtime performance at the program/code level?','SAT','SFP','SE71','SM59','A','SAT is the ABAP Runtime Analysis tool.'),
(89,'Performance','What is the main purpose of ST05?','Trace database access and other selected system interactions','Create classes','Maintain forms','Manage users','A','ST05 can trace SQL/database activity and related interactions.'),
(90,'Performance','Why can SELECT * be undesirable when only a few columns are needed?','It can transfer and process unnecessary data','It always causes a syntax error','It creates a new table','It disables indexes','A','Selecting only required columns can reduce data transfer and processing.'),
(91,'Performance','What is a common goal of performance tuning?','Reduce runtime and resource consumption while preserving correctness','Remove all indexes','Avoid all database access','Increase code complexity','A','Performance tuning aims for efficient resource use without changing intended behavior.'),
(92,'Performance','What can an SQL trace help identify?','Expensive or repeated database statements','Only UI colors','Only user passwords','Only transport owners','A','Trace data helps identify SQL statements and database access patterns that may need optimization.'),
(93,'ATC','What does ATC stand for in SAP development?','ABAP Test Cockpit','Advanced Transport Controller','ABAP Transaction Compiler','Application Table Checker','A','ATC is the ABAP Test Cockpit for static checks and quality analysis.'),
(94,'ATC','What type of issues can ATC identify?','Static code quality, syntax-related, performance, and clean-core relevant findings depending on checks','Only printer errors','Only network failures','Only database backups','A','ATC runs static checks and can identify many categories of code issues.'),
(95,'Remote Assessment','What is the purpose of remote assessment in SAP development governance?','Assess code quality and compliance remotely using defined tools/checks','Replace all developers','Create invoices','Manage printers','A','Remote assessment supports centralized or remote evaluation of development quality and compliance.'),
(96,'Open SQL','Which clause is used to restrict rows based on a condition?','WHERE','WHEN','FILTER ONLY','CHECK','A','WHERE filters rows according to a condition.'),
(97,'Open SQL','Which operation combines rows from two compatible internal tables into one table in ABAP?','APPEND','JOIN DATABASE','MERGE SQL','UNION TABLE','A','APPEND can add rows from one internal table to another; database UNION is a different SQL concept.'),
(98,'ABAP Dictionary','Which object is used to define a reusable structured type without necessarily creating a database table?','Structure','Lock object','Search help','Table pool','A','Structures define reusable data structures and can be used in programs and Dictionary objects.'),
(99,'OOP ABAP','Which principle hides implementation details behind a defined interface?','Encapsulation','Inheritance only','Compilation','Serialization','A','Encapsulation groups data and behavior and controls access to implementation details.'),
(100,'RAP','In RAP, what is a projection view used for?','Define a consumer-facing projection of the underlying business object model','Create a printer form','Replace the database schema','Store user passwords','A','Projection views expose a tailored subset/model for a specific service or use case.')
